-- The shipped recipe data (AzerothMercantileExchange_Crafting, generated by scripts/gen-recipes.py from the game's
-- client tables), loaded on demand: only when Crafting asks for it, never at login. Read through this module, which
-- applies hand fixes (OVERRIDES) on top of the generated rows and decodes their compact form.
--
--   CraftingData:Load()            -> true when the data is there (loads the addon the first time)
--   CraftingData:Recipe(spellID)   -> { profession, product, made, yellow, green, grey, reagents = {{id, n}...} }
--   CraftingData:Teaches(itemID)   -> { profession, rank, spells = {...} } for a recipe item (nil otherwise)
--   CraftingData:Build()           -> the client build the data was made from
local ADDON, ns = ...

local CraftingData = {}
ns.CraftingData = CraftingData

CraftingData.ADDON = ADDON .. "_Crafting"

-- Hand fixes, applied over the generated data (never edit the generated file): recipes[spellID] / items[itemID]
-- in the generated (compact) form, or false to drop a row. Each fix says why.
CraftingData.OVERRIDES = {
  recipes = {},
  items = {},
}

-- data: the generated table (AME_CraftingData); for specs, Use(data) skips loading the addon
function CraftingData:Use(data)
  self.data = data
  self.cache = {}
end

function CraftingData:Load()
  if self.data then
    return true
  end
  if not _G.AME_CraftingData then
    local load = (C_AddOns and C_AddOns.LoadAddOn) or _G.LoadAddOn
    local ok, loaded, reason = pcall(load, CraftingData.ADDON)
    if not (ok and loaded) then
      self.failed = tostring(reason or loaded)
      return false
    end
  end
  if type(_G.AME_CraftingData) ~= "table" then
    return false
  end
  self:Use(_G.AME_CraftingData)
  return true
end

function CraftingData:Build()
  return self.data and self.data.build
end

local function row(kind, id)
  local fix = CraftingData.OVERRIDES[kind][id]
  if fix ~= nil then
    return fix or nil
  end
  local d = CraftingData.data
  return d and d[kind][id]
end

function CraftingData:Recipe(spellID)
  local cached = self.cache and self.cache[spellID]
  if cached ~= nil then
    return cached or nil
  end
  local r = row("recipes", spellID)
  local out = false
  if r then
    out = {
      profession = r[1],
      product = r[2] ~= 0 and r[2] or nil, -- nil: an enchant (no item)
      made = r[3],
      yellow = r[4],
      grey = r[5],
      -- green isn't stored: halfway between yellow and grey, rounded down
      green = math.floor((r[4] + r[5]) / 2),
      reagents = {},
    }
    for i = 6, #r - 1, 2 do
      out.reagents[#out.reagents + 1] = { r[i], r[i + 1] }
    end
  end
  if self.cache then
    self.cache[spellID] = out
  end
  return out or nil
end

function CraftingData:Teaches(itemID)
  local r = row("items", itemID)
  if not r then
    return nil
  end
  local spells = {}
  for i = 3, #r do
    spells[#spells + 1] = r[i]
  end
  return { profession = r[1], rank = r[2], spells = spells }
end

-- every recipe spell of a profession (shipped data), unsorted
function CraftingData:ProfessionRecipes(profession)
  local out = {}
  for id in pairs(self.data and self.data.recipes or {}) do
    local r = self:Recipe(id)
    if r and r.profession == profession then
      out[#out + 1] = id
    end
  end
  return out
end
